def is_valid_input(lst):
    if len(lst) != 2:
        return False
    for s in lst:
        if not all(c in ['(', ')'] for c in s):
            return False
    return True

def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    if not is_valid_input(lst):
        return 'No'

    s1, s2 = lst
    for i in range(len(s1) + 1):
        for j in range(len(s2) + 1):
            new_str = s1[:i] + s2[j:]
            if is_balanced(new_str):
                return 'Yes'

    return 'No'

# Test cases
print(match_parens(['()(', ')']))  # Output: Yes
print(match_parens([')', ')']))     # Output: No

